const config = $input.first().json;

const ideias = [
  {
    tema: 'presente com significado',
    gancho: 'O presente pode acabar. A mensagem fica.',
    formato_conteudo: 'foto de produto + detalhe da mensagem',
    score: 92
  },
  {
    tema: 'processo artesanal',
    gancho: 'Da folha em branco a um cartão que não existe igual.',
    formato_conteudo: 'Reel curto de processo',
    score: 98
  },
  {
    tema: 'personalização',
    gancho: 'Feito à mão para alguém específico.',
    formato_conteudo: 'carrossel frente, interior e De/Para',
    score: 95
  }
];

return ideias.map((ideia, index) => ({
  json: {
    ...config,
    ideia_id: index + 1,
    ...ideia,
    origem_tendencia: 'protótipo local — substituir por pesquisa aprovada na fase 2'
  }
}));

const candidatas = $input.all().map(item => item.json);
const escolhida = [...candidatas].sort((a, b) => b.score - a.score)[0];

return [{
  json: {
    ...escolhida,
    candidatas: candidatas.map(({ ideia_id, tema, gancho, score }) => ({ ideia_id, tema, gancho, score }))
  }
}];

const d = $input.first().json;

const legenda = `${d.gancho}\n\nCada peça é desenhada e pintada individualmente em aquarela. O modelo padrão mede ${d.formato} e acompanha ${d.inclui}.\n\nR$ ${Number(d.preco).toFixed(2).replace('.', ',')}\n\n${d.cta}.\n\n#Aquarela #FeitoÀMão #CartãoArtesanal #NatalAutoral #Brasília`;

const promptImagem = `Fotografia editorial vertical 4:5 de um cartão artesanal de Natal em aquarela, preservando o produto real e sua caligrafia. Fundo marfim limpo, envelope kraft, pequenos ramos de eucalipto, luz natural suave. O cartão deve ser o elemento principal. Sem texto promocional adicional, sem logotipo, sem marca-d'água.`;

return [{
  json: {
    ...d,
    legenda,
    prompt_imagem: promptImagem,
    briefing_visual: 'Usar a foto real do N01 como referência; IA pode limpar o cenário, mas não deve inventar outro produto.',
    arquivo_visual_prototipo: 'assets/prototipo-instagram-n01-v2-natural.png',
    checklist_revisao: [
      'O produto da imagem corresponde ao produto real?',
      'Feliz Natal, De: e Para: estão corretos?',
      'Preço, formato e itens inclusos conferem?',
      'A legenda evita promessas e escassez falsas?',
      'Há autorização para publicar esta foto?'
    ]
  }
}];

const pacote = $input.first().json;

return [{
  json: {
    ...pacote,
    status: 'AGUARDANDO_APROVACAO_HUMANA',
    aprovado: false,
    proxima_acao: 'Revisar imagem, texto e dados antes de qualquer publicação.'
  }
}];
